import{_ as t,c as o,o as s,ae as a}from"./chunks/framework.Cd-3tpCq.js";const l=JSON.parse(`{"title":"Export Shipments","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-shipments-export","title":"Export Shipments (CSV)","description":"Download the shipments datagrid as a CSV file — the same data the admin Shipments \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/shipments/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output shipments.csv\\n","response":"# Binary response: a text/csv attachment is written to shipments.csv\\n# (Content-Disposition: attachment; filename=\\"shipments.csv\\"). Sample contents:\\n\\nID,\\"Order ID\\",\\"Total Qty\\",\\"Inventory Source\\",\\"Shipped To\\",\\"Shipment Date\\"\\n15,172,1,Default,\\"John Doe\\",\\"2026-04-23 22:06:13\\"\\n"},{"id":"admin-shipments-export-xlsx","title":"Export Shipments (XLSX)","description":"Download the shipments datagrid as an XLSX file — the same data the admin Shipments \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/shipments/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output shipments.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"shipments.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-shipments-export-xls","title":"Export Shipments (XLS)","description":"Download the shipments datagrid as an XLS file — the same data the admin Shipments \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/shipments/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output shipments.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"shipments.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/shipments/export.md","filePath":"api/rest-api/admin/sales/shipments/export.md"}`),n={name:"api/rest-api/admin/sales/shipments/export.md"};function r(i,e,d,p,h,c){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="export-shipments" tabindex="-1">Export Shipments <a class="header-anchor" href="#export-shipments" aria-label="Permalink to &quot;Export Shipments&quot;">​</a></h1><p>Downloads the shipments datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Sales → Shipments</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON. Requires the <code>sales.shipments.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/shipments/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the six datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Shipment id.</td></tr><tr><td><code>Order ID</code></td><td>The parent order&#39;s number.</td></tr><tr><td><code>Total Qty</code></td><td>Total quantity of items in the shipment.</td></tr><tr><td><code>Inventory Source</code></td><td>The source the shipment was dispatched from.</td></tr><tr><td><code>Shipped To</code></td><td>Name on the order&#39;s shipping address.</td></tr><tr><td><code>Shipment Date</code></td><td>When the shipment was created.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>; any other value returns <code>422</code>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/shipments/list.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>id</code>, <code>order_id</code>, <code>total_qty</code>, <code>inventory_source_name</code>, <code>shipped_to</code>, <code>order_date_from</code> / <code>_to</code>, <code>created_at_from</code> / <code>_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.shipments.view</code></p>',12)]))}const u=t(n,[["render",r]]);export{l as __pageData,u as default};
